use std::fs

struct Job {
    name: string,
    pri: int,
}

fn best(jobs: Vec<Job>) -> int {
    let mut b: int = 0
    let n: int = jobs.len() as int
    let mut i: int = 1
    while i < n {
        if jobs[i as usize].pri > jobs[b as usize].pri {
            b = i
        }
        i += 1
    }
    b
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut jobs: Vec<Job> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        let n: int = parts.len() as int
        if n == 3 && parts[0] == "add" {
            match parts[2].parse::<int>() {
                Ok(p) => jobs.push(Job { name: parts[1], pri: p }),
                Err(_) => println("error"),
            }
        } else if n == 1 && parts[0] == "pop" {
            if jobs.len() == 0 {
                println("empty")
            } else {
                let b = best(jobs)
                println(jobs[b as usize].name)
                jobs.remove(b as usize)
            }
        } else if n == 1 && parts[0] == "peek" {
            if jobs.len() == 0 {
                println("empty")
            } else {
                let b = best(jobs)
                println(jobs[b as usize].name)
            }
        } else if n == 1 && parts[0] == "size" {
            println("${jobs.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while jobs.len() > 0 {
        let b = best(jobs)
        println("${jobs[b as usize].name} ${jobs[b as usize].pri}")
        jobs.remove(b as usize)
    }
}

